files.content:
*:root {
    --aura: 13px;
    --aura-font-stack: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI",
      "Roboto", "Oxygen", "Ubuntu", "Cantarell", "Fira Sans", "Droid Sans",
      "Helvetica Neue", sans-serif;
    --aura-font-quotes: serif;
    --aura-grey: #f6f7f9;
    --aura-bg: #fff;
    --aura-text-primary: #030303;
    --aura-text-primary-inverse: #fff;
    --aura-accents-primary: #333;
    --aura-accents-secondary: #0882ba;
    --aura-accents-success: #045d3c;
    --aura-accents-success-bg: #e8fef7;
    --aura-accents-info: #0927ec;
    --aura-accents-info-bg: #e8ebfe;
    --aura-accents-warning: #5d5104;
    --aura-accents-warning-bg: #fefbe8;
    --aura-accents-danger: #8e3106;
    --aura-accents-danger-bg: #feefe8;
    --aura-input-radius: 6.5px;
    --aura-button-radius: 6.5px;
    --aura-input-bg: #f0f0f7;
    --aura-input-placeholder-color: rgba(51, 51, 51, 0.5);
    --aura-radius: 13px;
    --aura-opacity: 0.5;
    --aura-outline: #0927ec solid 2px;
    --aura-button-hover: #323232;
    --aura-link: var(--aura-text-primary);
    --aura-link-hover: #ededf5;
    --aura-selector: #d1fdef;
    --aura-loader: #d1fdef;
    --aura-skeleton-start: #c2cfd6;
    --aura-skeleton-end: #f0f3f5;
  }
  .valign {
    display: -webkit-box;
    display: -moz-box;
    display: -ms-flexbox;
    display: -webkit-flex;
    display: flex;
    justify-content: center;
    flex-direction: column;
  }
  .fluid {
    width: 100% !important;
  }
  .disabled,
  .button:disabled,
  .button-fill:disabled,
  .button-pill:disabled,
  .button-link:disabled,
  .button-menu:disabled,
  textarea:not(.default):disabled,
  input:not(.default):disabled,
  select:not(.default):disabled {
    opacity: var(--aura-opacity);
    cursor: default;
  }
  .typeahead {
    padding-left: calc(var(--aura) * 6);
  }
  .truncate {
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .action {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
  }

  @media only screen and (max-width: 767px) {
    .hide-small {
      display: none;
    }
  }
  @media screen and (min-width: 767px) and (max-width: 1155px) {
    .hide-medium {
      display: none;
    }
  }
  @media only screen and (min-width: 1155px) {
    .hide-large {
      display: none;
    }
  }
  .unset {
    all: unset;
  }
  .halo {
    display: flex;
    flex-wrap: wrap;
    flex-direction: row;
    width: 100%;
  }
  .reverse {
    flex-direction: row-reverse;
  }
  .aureole {
    display: grid;
    grid-gap: var(--aura);
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .aureole.one {
    grid-template-columns: minmax(0, 1fr);
  }
  .aureole.two {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .aureole.four {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .aureole.five {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
  .aureole.six {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }
  .aureole.twelve {
    grid-template-columns: repeat(12, minmax(0, 1fr));
  }
  @media only screen and (min-width: 767px) {
    .aureole.reverse .one {
      order: 2;
    }
    .aureole.reverse .two {
      order: 1;
    }
  }
  @media only screen and (max-width: 767px) {
    body .aureole:not(.fixed) {
      grid-template-columns: minmax(0, 1fr);
    }
  }
  .span-1 {
    grid-column: span 1;
  }
  .span-2 {
    grid-column: span 2;
  }
  .span-3 {
    grid-column: span 3;
  }
  .span-4 {
    grid-column: span 4;
  }
  .span-5 {
    grid-column: span 5;
  }
  .span-6 {
    grid-column: span 6;
  }
  .span-7 {
    grid-column: span 7;
  }
  .span-8 {
    grid-column: span 8;
  }
  .span-9 {
    grid-column: span 9;
  }
  .span-10 {
    grid-column: span 10;
  }
  .span-11 {
    grid-column: span 11;
  }
  .span-12 {
    grid-column: span 12;
  }
  @media only screen and (max-width: 767px) {
    [class*="span-"]:not(.fixed) {
      grid-column: span 1;
    }
  }
  .aureole.fixed {
    position: static;
  }
  [class*="span-"].fixed {
    position: static;
  }
  .warning {
    background-color: var(--aura-accents-warning-bg) !important;
    --aura-outline: solid 2px var(--aura-accents-warning);
  }
  .warning-text {
    color: var(--aura-accents-warning);
  }
  .info {
    background-color: var(--aura-accents-info-bg) !important;
    --aura-outline: solid 2px var(--aura-accents-info);
  }
  .info-text {
    color: var(--aura-accents-info);
  }
  .danger {
    background-color: var(--aura-accents-danger-bg) !important;
    --aura-outline: solid 2px var(--aura-accents-danger);
  }
  .danger-text {
    color: var(--aura-accents-danger);
  }
  .success {
    background-color: var(--aura-accents-success-bg) !important;
    --aura-outline: solid 2px var(--aura-accents-success);
  }
  .success-text {
    color: var(--aura-accents-success);
  }
  html {
    font-family: var(--aura-font-stack);
    line-height: 1.21053;
    -webkit-font-smoothing: antialiased;
    text-size-adjust: 100%;
    text-rendering: optimizelegibility;
    box-sizing: border-box;
  }
  pre {
    font-family: var(--aura-font-stack);
  }
  body {
    font-size: 1rem;
  }
  body h1,
  body h2,
  body h3,
  body h4,
  body h5,
  body h6,
  body p,
  body .h1,
  body .h2,
  body .h3,
  body .h4,
  body .h5,
  body .h6 {
    font-size: clamp(var(--min), var(--val), var(--max));
  }
  h1,
  .h1 {
    --min: 1.9838rem;
    --val: 4.029999999999999vw;
    --max: 3.052rem;
  }
  h2,
  .h2 {
    --min: 1.58665rem;
    --val: 4.029999999999999vw;
    --max: 2.441rem;
  }
  h3,
  .h3 {
    --min: 1.482rem;
    --val: 4.029999999999999vw;
    --max: 2.28rem;
  }
  h4,
  .h4,
  blockquote {
    --min: 1.26945rem;
    --val: 4.029999999999999vw;
    --max: 1.953rem;
  }
  h5,
  .h5 {
    --min: 1.17225rem;
    --val: 4.029999999999999vw;
    --max: 1.563rem;
  }
  h6,
  .h6 {
    --min: 1.0625rem;
    --val: 4.029999999999999vw;
    --max: 1.25rem;
  }
  .p {
    --min: 1rem;
    --val: 4.029999999999999vw;
    --max: 1rem;
  }
  p {
    margin: var(--aura) 0;
  }
  blockquote {
    font-family: var(--aura-font-quotes);
    text-transform: uppercase;
    font-weight: 600;
  }
  ul:not(.default) {
    margin: 0;
    padding: 0;
    list-style: none;
  }
  hr {
    border: 0;
  }
  .pad {
    padding: 45.5px var(--aura) 19.5px;
  }
  @media only screen and (max-width: 767px) {
    .pad {
      padding: 26px var(--aura) var(--aura) var(--aura);
    }
  }
  .aura {
    padding: var(--aura);
  }
  .inputer {
    padding: 0 var(--aura);
  }
  .aura-container,
  .smish,
  .smosh,
  .smash,
  .smush {
    margin: 0 auto;
  }

  .smish {
    max-width: 250px;
  }
  .smosh {
    max-width: 440px;
  }
  .smash {
    max-width: 740px;
  }
  .smush {
    max-width: 1032px;
  }
  .smesh {
    max-width: 1600px;
  }
  .skeleton {
    animation: skeleton-loading 1s linear infinite alternate;
    border-radius: var(--aura-radius);
  }
  @-moz-keyframes skeleton-loading {
    0% {
      background-color: var(--aura-skeleton-start);
    }
    100% {
      background-color: var(--aura-skeleton-end);
    }
  }
  @-webkit-keyframes skeleton-loading {
    0% {
      background-color: var(--aura-skeleton-start);
    }
    100% {
      background-color: var(--aura-skeleton-end);
    }
  }
  @-o-keyframes skeleton-loading {
    0% {
      background-color: var(--aura-skeleton-start);
    }
    100% {
      background-color: var(--aura-skeleton-end);
    }
  }
  @keyframes skeleton-loading {
    0% {
      background-color: var(--aura-skeleton-start);
    }
    100% {
      background-color: var(--aura-skeleton-end);
    }
  }
  a {
    text-decoration: none;
    color: var(--aura-link);
  }
  a:visited:not([class*="button-"]) {
    color: inherit;
  }
  a:active {
    outline: var(--aura-outline);
  }
  .button,
  .button-fill,
  .button-pill,
  .button-link,
  .button-menu {
    cursor: pointer;
    box-sizing: border-box;
    margin: 0;
    letter-spacing: normal;
    word-spacing: normal;
    text-transform: none;
    text-indent: 0;
    text-shadow: none;
    font: inherit;
    -webkit-box-align: center;
    -ms-flex-align: center;
    align-items: center;
    border-radius: var(--aura-button-radius);
    -webkit-border-radius: var(--aura-button-radius);
    -moz-border-radius: var(--aura-button-radius);
    transition: 300ms background cubic-bezier(0.4, 0, 0.6, 1) linear;
    -webkit-transition: 300ms background cubic-bezier(0.4, 0, 0.6, 1) linear;
    -moz-transition: 300ms background cubic-bezier(0.4, 0, 0.6, 1) linear;
    font-weight: 600;
    display: inline-flex;
    height: calc(var(--aura) * 4);
    padding: 0 calc(var(--aura) * 2);
    border: 2px solid;
    transition: transform 250ms cubic-bezier(0.2, 0.8, 0.4, 1);
    justify-content: center;
  }
  .button:hover.button:hover:not(:disabled),
  .button-fill:hover.button-fill:hover:not(:disabled),
  .button-pill:hover.button-pill:hover:not(:disabled),
  .button-link:hover.button-link:hover:not(:disabled),
  .button-menu:hover.button-menu:hover:not(:disabled) {
    transform: scale(1.03);
  }
  .button:active.button:hover:not(:disabled),
  .button-fill:active.button-fill:hover:not(:disabled),
  .button-pill:active.button-pill:hover:not(:disabled),
  .button-link:active.button-link:hover:not(:disabled),
  .button-menu:active.button-menu:hover:not(:disabled) {
    transform: scale(0.97);
    outline: var(--aura-outline);
  }
  .button-fill {
    border-color: var(--aura-accents-primary);
    color: var(--aura-text-primary-inverse);
    background-color: var(--aura-accents-primary);
  }
  .button-fill:hover:not(:disabled),
  .button-fill.active {
    background-color: var(--aura-button-hover);
  }
  .button-pill {
    color: var(--aura-link);
    border-color: var(--aura-link);
    background-color: transparent;
  }
  .button-pill:hover:not(:disabled),
  .button-pill.active {
    background-color: var(--aura-link-hover);
  }
  .button-link {
    color: var(--aura-link);
    border: 0;
    text-decoration: underline;
    background-color: transparent;
  }
  .button-link:hover:not(:disabled),
  .button-link.active {
    color: var(--aura-base-color);
    background-color: var(--aura-link-hover);
  }
  .button-menu {
    font-weight: bold;
    padding: calc(var(--aura) * 0.5) var(--aura);
    border: 0;
    text-decoration: none;
  }
  .inputer {
    position: relative;
    margin-bottom: calc(var(--aura) * 1.5);
  }
  .inputer-group {
    position: relative;
    box-sizing: border-box;
  }
  .inputer-group label:not(.default) {
    position: absolute;
    transform-origin: top left;
    transform: translate(26px, 0);
  }
  .inputer-group .typeahead {
    padding-left: 78px;
  }
  .inputer-group .typeahead + label {
    transform: translate(78px, 0);
  }
  label:not(.default),
  input:not(.default) {
    transition: all 0.1s ease-in-out;
    touch-action: manipulation;
  }
  textarea:not(.default) {
    border-radius: var(--aura-input-radius);
    -webkit-border-radius: var(--aura-input-radius);
    -moz-border-radius: var(--aura-input-radius);
    width: 100%;
    border: 0;
    background-color: var(--aura-input-bg);
    box-sizing: border-box;
    box-shadow: none;
    color: var(--aura-accents-10);
    font-family: inherit;
    font: inherit;
    height: 106px;
    padding: calc(var(--aura) * 2);
  }
  textarea:not(.default):focus {
    background: var(--aura-input-bg);
    outline: var(--aura-outline);
  }
  textarea:not(.default)::placeholder {
    color: var(--aura-input-placeholder-color);
  }
  textarea:not(.default):placeholder-shown + label {
    cursor: text;
    max-width: 66.66%;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    transform-origin: left bottom;
    opacity: 0;
    z-index: -1;
  }
  textarea:not(.default):not(:placeholder-shown) + label {
    opacity: 1;
    cursor: pointer;
    z-index: 0;
  }
  input:not(.default) {
    border-radius: var(--aura-input-radius);
    -webkit-border-radius: var(--aura-input-radius);
    -moz-border-radius: var(--aura-input-radius);
    width: 100%;
    background-color: var(--aura-input-bg);
    border: 0;
    box-sizing: border-box;
    box-shadow: none;
    color: var(--aura-accents-10);
    font-family: inherit;
    font: inherit;
    height: calc(var(--aura) * 4);
    padding: calc(var(--aura) * 2);
    line-height: calc(var(--aura) * 4) px;
    cursor: text;
  }
  input:not(.default)[type="file"] {
    padding-top: var(--aura);
  }
  input:not(.default):focus {
    background: var(--aura-input-bg);
    outline: var(--aura-outline);
  }
  input:not(.default)::placeholder {
    color: var(--aura-input-placeholder-color);
  }
  input:not(.default):placeholder-shown + label {
    cursor: text;
    max-width: 66.66%;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    transform-origin: left bottom;
    opacity: 0;
    z-index: -1;
  }
  input:not(.default):not(:placeholder-shown) + label {
    opacity: 1;
    cursor: pointer;
    z-index: 0;
  }
  .inputer input:not(.default):not(:placeholder-shown):not(.naked) {
    padding: calc(var(--aura) * 2.5) calc(var(--aura) * 2) calc(var(--aura) * 1.5)
      calc(var(--aura) * 2);
  }
  select:not(.default) {
    color: var(--aura-accents-10);
    background-color: var(--aura-input-bg);
    width: 100%;
    font-family: inherit;
    font: inherit;
    height: calc(var(--aura) * 4);
    padding: 0 calc(var(--aura) * 2);
    line-height: calc(var(--aura) * 4) px;
    box-sizing: border-box;
    border: 0;
    -webkit-appearance: none;
    -moz-appearance: none;
    appearance: none;
    border-radius: var(--aura-input-radius);
    -webkit-border-radius: var(--aura-input-radius);
    -moz-border-radius: var(--aura-input-radius);
  }
  select:not(.default):focus {
    outline: var(--aura-outline);
  }

  /*
   * Mobile UX: form control font-size must stay ≥17px so iOS Safari does not
   * zoom on focus. Unlayered intent — keep in base sheet shipped with css-main.
   * See fundations-typography rule / DESIGN.md.
   */
  input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="file"]):not([type="hidden"]):not([type="button"]):not([type="submit"]):not([type="reset"]):not([type="image"]):not([type="color"]),
  textarea,
  select {
    font-size: max(1rem, 17px);
  }


  .icon {
    width: 1em;
    height: 1em;
    display: inline-block;
    line-height: 1em;
    flex-shrink: 0;
    vertical-align: middle;
  }

  .nav-list {
    align-items: center;
    cursor: default;
    margin: 0 -10px;
    width: auto;
    height: calc(var(--aura) * 4);
    display: -webkit-box;
    display: -moz-box;
    display: -ms-flexbox;
    display: -webkit-flex;
    display: flex;
    -webkit-box-pack: justify;
    -ms-flex-pack: justify;
    justify-content: space-between;
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
  }
  .nav-list.start {
    justify-content: flex-start;
  }
  .nav-list .item {
    line-height: 2.7;
    letter-spacing: -0.01em;
    position: relative;
    z-index: 1;
    display: inline-block;
    padding: 0 var(--aura);
    opacity: 1;
    background: no-repeat;
    text-decoration: none;
    outline-offset: -7px;
  }
  html {
    margin: 0;
    padding: 0;
    color: var(--aura-text-primary);
  }
  body {
    margin: 0;
    padding: 0;
    min-width: 320px;
    max-width: 100%;
    overflow-x: hidden;
    background-color: var(--aura-bg);
  }
  .page {
    padding: 0;
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
  }
  .page-pancake {
    display: grid;
    grid-template-rows: auto 1fr auto;
    min-height: 100vh;
  }

  .page-dashboard {
    display: grid;
    grid-template-rows: auto 1fr auto;
    grid-template-columns: 100px 1fr;
    min-height: 100vh;
  }
  * {
    box-sizing: border-box;
    touch-action: manipulation;
  }

  *::selection {
    color: var(--aura-accents-primary);
    background: var(--aura-selector);
  }

  #nprogress {
    pointer-events: none;
  }
  #nprogress .bar {
    background: var(--aura-loader);
  }
